"""build_table_domain.py — 从任意 profile 配置生成该领域的拼音键表

支持两类来源（同一份配置里可混用）:
  ① apps/urls/files 的 name+aliases → (launch_app/open_url/open_file, 名称, ["打开X","启动X",…])
  ② intents 里每个意图若在 triggers 里有字面短语表(如 ops_disk: ["查磁盘","磁盘",…])
     → (意图, None, [短语…])      ← 运维/游戏域的字面命令

用法:
  python -m opencode_fastpath.build_table_domain --config intent_config.json --table opencode_fastpath/table_office.json
  python -m opencode_fastpath.build_table_domain --config ops/profiles/ops-v1/intent_config.ops.json --table opencode_fastpath/table_ops.json
"""
from __future__ import annotations

import argparse
import json
from pathlib import Path

from .fastpath import FastPath
from .pinyin import Encoder

ROOT = Path(__file__).resolve().parent.parent
OPEN_PREFIX = ("打开", "启动", "开一下", "运行", "上", "进入", "看看", "看", "开")


def entries_from_config(cfg: dict):
    out = []
    for kind, intent in (("apps", "launch_app"), ("urls", "open_url"), ("files", "open_file")):
        for it in cfg.get(kind) or []:
            names = [it.get("name", "")] + list(it.get("aliases") or [])
            trig = [p + n for n in names if n for p in OPEN_PREFIX]
            if trig:
                out.append((intent, it.get("name", ""), trig))
    tr = cfg.get("triggers") or {}
    ids = [i.get("id") for i in (cfg.get("intents") or [])]
    for iid in ids:
        ph = tr.get(iid)
        if isinstance(ph, list) and ph:
            out.append((iid, None, [str(x) for x in ph if str(x).strip()]))
    return out


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--config", required=True)
    ap.add_argument("--table", required=True)
    a = ap.parse_args()
    cfg = json.loads(Path(a.config).read_text(encoding="utf-8"))
    rows = entries_from_config(cfg)

    fp = FastPath(table_path=a.table, mode="off")
    fp.entries = []
    fp.enc = Encoder()
    n_trig = 0
    for intent, arg, trig in rows:
        fp.install(intent, arg, trig, additive=True, markers={"source": a.config})
        n_trig += len(trig)
    st = fp.stats()
    print(f"[OPENCODE] 领域表生成: {Path(a.config).name} → {Path(a.table).name}")
    print(f"   条目 {len(fp.entries)}  触发器 {n_trig}  音节 {len(fp.enc.ids)}  "
          f"行(全串/前缀) {st['full']}/{st['prefix']}  表体 {st['bytes']}B")
    for intent, arg, trig in rows[:3]:
        r = fp.route(trig[0])
        print(f"   例: 「{trig[0]}」 → {r['decision']} {r.get('intent') or ''} arg={r.get('arg')}")


if __name__ == "__main__":
    main()
